export function UX({
  friction = "{{friction}}",
  showTimings = {{showTimings}},
  accent = "{{accent}}",
}) {
  const steps = ["Find product", "Add to basket"];
  if (friction === "high") steps.push("Create an account", "Verify email", "Enter address twice");
  steps.push("Checkout");
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430" }}>
      <ol style={{ margin: 0, paddingLeft: 18 }}>
        {steps.map((s) => (<li key={s} style={{ padding: "3px 0" }}>{s}</li>))}
      </ol>
      {showTimings && <p style={{ margin: "10px 0 0", fontWeight: 600, color: accent }}>Estimated task time: <strong>{friction === "low" ? "40s" : "4 min"}</strong></p>}
      <p style={{ margin: "8px 0 0", fontSize: 11, color: "#241430aa" }}>The same task, {friction} friction &mdash; how it feels to accomplish, not just how it looks</p>
    </div>
  );
}
